// MT6701 frame parsing, CRC6, wrap, multi-turn count, PLL and getters.
// Module: #4   Milestone: M1-M2
//
// Hard-coded frames were generated by an independent CRC6 reference
// (x^6 + x + 1, MSB first, init 0). They test the code against that
// assumption; test_crc6_real_frame is the one that will prove it on hardware.

#include "unity.h"
#include "encoder_mt6701.h"
#include <math.h>

#define TOLERANCE 1e-4f
#define PI_F      3.14159265f
#define CPR       16384

void setUp(void) {}
void tearDown(void) {}

// ---------------------------------------------------------------- helpers

static const encoder_config_t test_cfg = {
    .cnt_per_rev    = CPR,
    .gear_ratio     = 9.0f,
    .pll_bandwidth  = 1000.0f,  // rad/s
    .Ts             = 50e-6f,   // 20 kHz
    .max_bad_in_row = 3,
};

// Build a frame with a correct CRC. Uses encoder_crc6(), which the
// hard-coded tests below check on its own first.
static uint32_t make_frame(uint16_t angle, uint8_t mg)
{
    uint32_t data_18 = ((uint32_t)(angle & 0x3FFF) << 4) | (mg & 0x0F);
    return (data_18 << 6) | encoder_crc6(data_18);
}

// Feed n good frames, moving the raw angle by step counts each time.
// Steps must stay under half a turn or wrap() picks the other direction.
static void feed_steps(encoder_t *enc, int32_t *angle, int32_t step, int n)
{
    for (int k = 0; k < n; k++)
    {
        *angle = ((*angle + step) % CPR + CPR) % CPR;
        TEST_ASSERT_EQUAL(ENCODER_OK, encoder_update(enc, make_frame((uint16_t)*angle, 0)));
    }
}

// ------------------------------------------------------------------ crc6

// crc6 on a captured real frame
static void test_crc6_real_frame(void)
{
    // Replace with a frame captured from the chip on the logic analyzer:
    // TEST_ASSERT_EQUAL_HEX8(captured & 0x3F, encoder_crc6(captured >> 6));
    TEST_IGNORE_MESSAGE("needs a frame captured from the real MT6701");
}

// crc6 on reference frames: the low 6 bits are the CRC of the top 18
static void test_crc6_known_values(void)
{
    TEST_ASSERT_EQUAL_HEX8(0x2B, encoder_crc6(0xAAA82B >> 6));
    TEST_ASSERT_EQUAL_HEX8(0x1F, encoder_crc6(0xFFFC1F >> 6));
    TEST_ASSERT_EQUAL_HEX8(0x06, encoder_crc6(0x0FA006 >> 6));
    TEST_ASSERT_EQUAL_HEX8(0x00, encoder_crc6(0x000000 >> 6));
}

// crc6 with one data bit flipped --> crc6 catches errors
static void test_crc6_faulty_frame(void)
{
    uint32_t good = 0x0FA006;
    uint32_t bad  = 0x0FA406;   // D0 (bit 10) flipped

    TEST_ASSERT_EQUAL_HEX8(0x06, encoder_crc6(good >> 6));
    TEST_ASSERT_NOT_EQUAL(0x06, encoder_crc6(bad >> 6));
}

// ---------------------------------------------------------------- unpack

// unpack() a real proper frame
static void test_unpack_real_frame(void)
{
    encoder_frame_t f;

    encoder_unpack(0xAAA82B, &f);
    TEST_ASSERT_EQUAL_UINT16(10922, f.data);
    TEST_ASSERT_EQUAL_UINT8(0x0, f.mg);
    TEST_ASSERT_EQUAL_HEX8(0x2B, f.crc);

    encoder_unpack(0xFFFC1F, &f);
    TEST_ASSERT_EQUAL_UINT16(16383, f.data);
    TEST_ASSERT_EQUAL_UINT8(0x0, f.mg);
    TEST_ASSERT_EQUAL_HEX8(0x1F, f.crc);

    encoder_unpack(0x0FA21E, &f);
    TEST_ASSERT_EQUAL_UINT16(1000, f.data);
    TEST_ASSERT_EQUAL_UINT8(0x8, f.mg);
    TEST_ASSERT_EQUAL_HEX8(0x1E, f.crc);
}

// Junk above bit 23 must not leak into any field
static void test_unpack_ignores_top_byte(void)
{
    encoder_frame_t f;

    encoder_unpack(0xFF0FA006, &f);
    TEST_ASSERT_EQUAL_UINT16(1000, f.data);
    TEST_ASSERT_EQUAL_UINT8(0x0, f.mg);
    TEST_ASSERT_EQUAL_HEX8(0x06, f.crc);
}

// ----------------------------------------------------------- frame_valid

// frame_valid() on a Mg = 2 (weak field) but valid CRC --> only checks CRC
static void test_frame_valid(void)
{
    encoder_frame_t f;

    encoder_unpack(0x0FA080, &f);   // weak field, CRC correct
    TEST_ASSERT_TRUE(encoder_frame_valid(&f));

    encoder_unpack(0x0FA046, &f);   // looks like "field strong" but CRC wrong
    TEST_ASSERT_FALSE(encoder_frame_valid(&f));

    encoder_unpack(0xFF0FA006, &f); // junk top byte, still valid
    TEST_ASSERT_TRUE(encoder_frame_valid(&f));
}

// ------------------------------------------------------------------ wrap

// wrap(5, 16380) = +9 and wrap(16380, 5) = -9
// crossing zero in both directions
static void test_wrap_crossing_zero(void)
{
    TEST_ASSERT_EQUAL_INT32(9,  encoder_wrap(5, 16380, CPR));
    TEST_ASSERT_EQUAL_INT32(-9, encoder_wrap(16380, 5, CPR));
}

// No wrap needed for small steps
static void test_wrap_small_steps(void)
{
    TEST_ASSERT_EQUAL_INT32(50,  encoder_wrap(1050, 1000, CPR));
    TEST_ASSERT_EQUAL_INT32(-50, encoder_wrap(1000, 1050, CPR));
    TEST_ASSERT_EQUAL_INT32(0,   encoder_wrap(1000, 1000, CPR));
}

// wrap(8191, 0) and wrap(8192, 0): result range is -8192..+8191
static void test_wrap_boundary(void)
{
    TEST_ASSERT_EQUAL_INT32(8191,  encoder_wrap(8191, 0, CPR));
    TEST_ASSERT_EQUAL_INT32(-8192, encoder_wrap(8192, 0, CPR));
    TEST_ASSERT_EQUAL_INT32(-8192, encoder_wrap(0, 8192, CPR));
    TEST_ASSERT_EQUAL_INT32(-8191, encoder_wrap(0, 8191, CPR));
}

// ---------------------------------------------------------------- update

// First good frame sets count to the raw angle, not 0
static void test_update_first_frame(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    TEST_ASSERT_FALSE(encoder_is_healthy(&enc));

    TEST_ASSERT_EQUAL(ENCODER_OK, encoder_update(&enc, 0x0FA006));
    TEST_ASSERT_TRUE(enc.count == 1000);
    TEST_ASSERT_EQUAL_UINT16(1000, encoder_get_data(&enc));
    TEST_ASSERT_TRUE(encoder_is_healthy(&enc));
}

// update() across zero with the hard-coded wrap pair
static void test_update_wrap_pair(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);

    encoder_update(&enc, 0xFFF00C);     // 16380
    encoder_update(&enc, 0x001435);     // 5
    TEST_ASSERT_TRUE(enc.count == 16380 + 9);

    encoder_update(&enc, 0xFFF00C);     // back to 16380
    TEST_ASSERT_TRUE(enc.count == 16380);
}

// update() fed 3 full forward turns, then 2 back
static void test_update_3_fwd_2_back_frames(void)
{
    encoder_t enc;
    int32_t angle = 0;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(0, 0));

    feed_steps(&enc, &angle, 1024, 48);     // 3 turns forward
    TEST_ASSERT_TRUE(enc.count == 3 * CPR);

    feed_steps(&enc, &angle, -1024, 32);    // 2 turns back
    TEST_ASSERT_TRUE(enc.count == 1 * CPR);
    TEST_ASSERT_EQUAL_UINT16(0, encoder_get_data(&enc));
}

// update() with a bad CRC frame
static void test_update_bad_crc_frame(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);

    encoder_update(&enc, 0x0FA006);     // good, 1000
    TEST_ASSERT_EQUAL(ENCODER_ERR_CRC, encoder_update(&enc, 0x0FA406));

    TEST_ASSERT_TRUE(enc.count == 1000);            // position held
    TEST_ASSERT_EQUAL_UINT16(1000, encoder_get_data(&enc));
    TEST_ASSERT_EQUAL_UINT32(1, enc.crc_err);
    TEST_ASSERT_EQUAL_UINT16(1, enc.bad_in_row);
    TEST_ASSERT_TRUE(encoder_is_healthy(&enc));     // one bad frame is tolerated
}

// CRC is checked before Mg: a corrupted frame whose Mg reads "strong"
// must be reported as a CRC error, not a field error
static void test_update_crc_checked_before_mg(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, 0x0FA006);

    TEST_ASSERT_EQUAL(ENCODER_ERR_CRC, encoder_update(&enc, 0x0FA046));
    TEST_ASSERT_EQUAL_UINT32(1, enc.crc_err);
    TEST_ASSERT_EQUAL_UINT32(0, enc.field_err);
}

// update() with max_bad_in_row bad frames --> reports unhealthy
static void test_update_with_max_bad_frames(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, 0x0FA006);

    TEST_ASSERT_EQUAL(ENCODER_ERR_FIELD_WEAK,   encoder_update(&enc, 0x0FA080));
    TEST_ASSERT_TRUE(encoder_is_healthy(&enc));
    TEST_ASSERT_EQUAL(ENCODER_ERR_FIELD_STRONG, encoder_update(&enc, 0x0FA045));
    TEST_ASSERT_TRUE(encoder_is_healthy(&enc));
    TEST_ASSERT_EQUAL(ENCODER_ERR_OVERSPEED,    encoder_update(&enc, 0x0FA21E));
    TEST_ASSERT_FALSE(encoder_is_healthy(&enc));    // 3rd bad in a row

    TEST_ASSERT_EQUAL_UINT32(3, enc.field_err);
    TEST_ASSERT_TRUE(enc.count == 1000);            // none of them moved the count
}

// update() with good frames after an error --> should recover
static void test_update_good_frames_after_error(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, 0x0FA006);
    for (int k = 0; k < 3; k++)
    {
        encoder_update(&enc, 0x0FA406);
    }
    TEST_ASSERT_FALSE(encoder_is_healthy(&enc));

    TEST_ASSERT_EQUAL(ENCODER_OK, encoder_update(&enc, 0x0FA006));
    TEST_ASSERT_EQUAL_UINT16(0, enc.bad_in_row);
    TEST_ASSERT_TRUE(encoder_is_healthy(&enc));
    TEST_ASSERT_EQUAL_UINT32(3, enc.crc_err);       // lifetime count is kept
}

// Push button bit alone is not a fault
static void test_update_button_bit_ignored(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, 0x0FA006);

    TEST_ASSERT_EQUAL(ENCODER_OK, encoder_update(&enc, 0x0FA10A));
    TEST_ASSERT_EQUAL_UINT16(0, enc.bad_in_row);
}

// set_cnt() moves the multi-turn count (homing) without touching raw
static void test_set_cnt(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, 0x0FA006);

    encoder_set_cnt(&enc, 5 * CPR + 1000);
    TEST_ASSERT_TRUE(enc.count == 5 * CPR + 1000);
    TEST_ASSERT_EQUAL_UINT16(1000, encoder_get_data(&enc));

    encoder_update(&enc, make_frame(1010, 0));
    TEST_ASSERT_TRUE(enc.count == 5 * CPR + 1010);
}

// ------------------------------------------------------------------- PLL

// PLL fed a constant-speed ramp
static void test_pll_const_speed(void)
{
    encoder_t enc;
    int32_t angle = 0;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(0, 0));

    feed_steps(&enc, &angle, 10, 2000);     // 10 counts per 50 us

    float expected = 10.0f / test_cfg.Ts * 2.0f * PI_F / CPR;   // ~76.7 rad/s
    TEST_ASSERT_FLOAT_WITHIN(0.01f * expected, expected, encoder_get_motor_velocity(&enc));
    TEST_ASSERT_FLOAT_WITHIN(0.01f * expected / 9.0f, expected / 9.0f,
                             encoder_get_output_velocity(&enc));
}

// PLL tracks reverse direction too
static void test_pll_const_speed_reverse(void)
{
    encoder_t enc;
    int32_t angle = 8000;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(8000, 0));

    feed_steps(&enc, &angle, -10, 2000);

    float expected = -10.0f / test_cfg.Ts * 2.0f * PI_F / CPR;
    TEST_ASSERT_FLOAT_WITHIN(0.01f * -expected, expected, encoder_get_motor_velocity(&enc));
}

// pll fed a stationary angle --> vel_estimate settles to 0
static void test_pll_with_stationary_angle(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);

    for (int k = 0; k < 1000; k++)
    {
        encoder_update(&enc, 0x0FA006);
    }
    TEST_ASSERT_EQUAL_FLOAT(0.0f, enc.vel_estimate);
    TEST_ASSERT_EQUAL_FLOAT(0.0f, encoder_get_motor_velocity(&enc));
}

// Shaft on the edge between two counts: reading flickers 1000/1001.
// Velocity must stay near 0 (well under 0.5 rpm), not drift.
static void test_pll_flicker_between_counts(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(1000, 0));

    float worst = 0.0f;
    for (int k = 0; k < 2000; k++)
    {
        encoder_update(&enc, make_frame((k & 1) ? 1001 : 1000, 0));
        float v = fabsf(encoder_get_motor_velocity(&enc));
        if (k > 200 && v > worst)
        {
            worst = v;
        }
    }
    TEST_ASSERT_FLOAT_WITHIN(0.05f, 0.0f, worst);   // 0.05 rad/s = 0.48 rpm
}

// --------------------------------------------------------------- getters

// output angle after 9 motor turns --> equals exactly 1 output revolution (2pi) with gear ratio 9
static void test_output_angle_after_9_turns(void)
{
    encoder_t enc;
    int32_t angle = 0;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(0, 0));

    feed_steps(&enc, &angle, 1024, 144);    // 9 motor turns

    TEST_ASSERT_FLOAT_WITHIN(TOLERANCE, 9.0f * 2.0f * PI_F, encoder_get_motor_angle(&enc));
    TEST_ASSERT_FLOAT_WITHIN(TOLERANCE, 2.0f * PI_F, encoder_get_output_angle(&enc));
}

// Quarter turn from zero
static void test_motor_angle_quarter_turn(void)
{
    encoder_t enc;
    encoder_init(&enc, &test_cfg);
    encoder_update(&enc, make_frame(4096, 0));

    TEST_ASSERT_FLOAT_WITHIN(TOLERANCE, PI_F / 2.0f, encoder_get_motor_angle(&enc));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_crc6_real_frame);
    RUN_TEST(test_crc6_known_values);
    RUN_TEST(test_crc6_faulty_frame);
    RUN_TEST(test_unpack_real_frame);
    RUN_TEST(test_unpack_ignores_top_byte);
    RUN_TEST(test_frame_valid);
    RUN_TEST(test_wrap_crossing_zero);
    RUN_TEST(test_wrap_small_steps);
    RUN_TEST(test_wrap_boundary);
    RUN_TEST(test_update_first_frame);
    RUN_TEST(test_update_wrap_pair);
    RUN_TEST(test_update_3_fwd_2_back_frames);
    RUN_TEST(test_update_bad_crc_frame);
    RUN_TEST(test_update_crc_checked_before_mg);
    RUN_TEST(test_update_with_max_bad_frames);
    RUN_TEST(test_update_good_frames_after_error);
    RUN_TEST(test_update_button_bit_ignored);
    RUN_TEST(test_set_cnt);
    RUN_TEST(test_pll_const_speed);
    RUN_TEST(test_pll_const_speed_reverse);
    RUN_TEST(test_pll_with_stationary_angle);
    RUN_TEST(test_pll_flicker_between_counts);
    RUN_TEST(test_output_angle_after_9_turns);
    RUN_TEST(test_motor_angle_quarter_turn);
    return UNITY_END();
}
